int main(){std::string error;SceneRenderer renderer;SceneLayout layout;layout.width=16;layout.height=4;layout.columns=layout.rows=32;check(renderer.configure(layout,error),"small native compositor extent");renderer.establishBlankAssets();GraphicsTransfer tile;tile.destination=32;tile.decoded.assign(32,0x11);check(renderer.applyTransfer(tile,error)&&renderer.fillPlaneCells(0,0,0,1,1,0x2001,error),"native palette1 indexed source cells");std::vector<uint16_t> colors(128,0);colors[17]=0x000e;check(renderer.setPalette(colors,0,error),"base source palette");SceneImage baseline;check(renderer.render({},kSceneRGB888,baseline,error),"ordinary picture baseline");std::vector<ScenePaletteSpan> spans(4);spans[0].row=1;spans[0].column=3;spans[0].firstColor=17;spans[0].colors={0x0e00};spans[1].row=2;spans[1].firstColor=17;spans[1].colors={0x00e0};spans[2]=spans[1];spans[2].colors={0x0e00};spans[3].row=3;spans[3].firstColor=0;spans[3].colors={0x000e};SceneImage image;check(renderer.render({},kSceneRGB888,image,error,&spans)&&image.indexed==baseline.indexed,"palette publication changes RGB after composition without replacing indexed source pixels");for(unsigned y=0;y<4;++y)for(unsigned x=0;x<16;++x){bool blue=x<8&&(y>1||(y==1&&x>=3));bool red=(x<8&&!blue)||(x>=8&&y==3);check(pixel(image,x,y,red?238:0,0,blue?238:0),"exact display position and cumulative source-order publication");}SceneImage again;check(renderer.render({},kSceneRGB888,again,error)&&again.rgb==baseline.rgb,"ephemeral publications never mutate retained source palette");auto bad=spans;bad[1].row=0;check(!renderer.render({},kSceneRGB888,image,error,&bad),"out-of-order publication fails");bad=spans;bad[0].column=16;check(!renderer.render({},kSceneRGB888,image,error,&bad),"outside-row position rejected");bad=spans;bad[0].firstColor=64;check(!renderer.render({},kSceneRGB888,image,error,&bad),"unknown palette extent rejected");bad=spans;bad[0].colors={0xffff};check(!renderer.render({},kSceneRGB888,image,error,&bad),"unsupported source color rejected");
 std::vector<bool> known(128,false);for(unsigned i=80;i<128;++i){known[i]=true;colors[i]=uint16_t((i&7)*2);}std::vector<uint16_t> lower;check(readLowerViewPalette(colors,known,lower,error)&&lower.size()==48&&lower.front()==colors[80]&&lower.back()==colors[127],"source80..127 only, text colors64..79 not required");std::vector<ScenePaletteSpan> lowerSpans;check(lowerViewPaletteSpans(colors,known,lowerSpans,error)&&lowerSpans.size()==12,"twelve recovered source publications");for(unsigned g=0;g<12;++g)check(lowerSpans[g].row==136+g&&lowerSpans[g].column==0&&lowerSpans[g].firstColor==16+4*g&&lowerSpans[g].colors==std::vector<uint16_t>(colors.begin()+80+4*g,colors.begin()+84+4*g),"source-order four-color payload at exact observed full-row boundary");auto retainedSpans=lowerSpans;auto saved=lower;known[90]=false;check(!readLowerViewPalette(colors,known,lower,error)&&lower==saved,"unknown secondary color cannot replace live payload");check(!lowerViewPaletteSpans(colors,known,lowerSpans,error)&&lowerSpans.size()==retainedSpans.size()&&lowerSpans[11].colors==retainedSpans[11].colors,"failed scheduler extraction retains previous publication payload");known[90]=true;colors[90]=0xffff;check(!readLowerViewPalette(colors,known,lower,error)&&lower==saved,"bad lower palette rejects transactionally");check(decodeGameLayoutRequest(0)==kGameLayoutUnchanged&&decodeGameLayoutRequest(255)==kGameLayoutTall&&decodeGameLayoutRequest(1)==kGameLayoutWide&&decodeGameLayoutRequest(65535)==kGameLayoutWide,"controller8 consumes exact source word policy");std::printf("Native palette publication: %u checks,0 failures\n",checks);return 0;}
